    public void testUnknownValueFailsByDefault() throws Exception {
        JsonMapper mapper = JsonMapper.builder().build();
        try {
            mapper.readValue("\"nope\"", SimpleFactoryEnum.class);
            fail("Should not accept unknown enum value by default");
