    public void testZeroArgsFactoryCreator() throws Exception {
        JsonMapper mapper = JsonMapper.builder().build();
        assertEquals(ZeroArgFactoryEnum.SINGLETON,
                mapper.readValue("\"not-an-enum-name\"", ZeroArgFactoryEnum.class));
    }
